/* ── Scrollbars: embedded, minimal, themed (no white OS default) ──── */
* {
  scrollbar-width: thin;                                   /* Firefox */
  scrollbar-color: var(--border) transparent;
}
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: transparent; }
*::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-pill);
  border: 2px solid transparent;
  background-clip: content-box;
  transition: background var(--dur-fast) var(--ease);
}
*::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.22);
  background-clip: content-box;
}
*::-webkit-scrollbar-corner { background: transparent; }

body {
  background: var(--bg);
  color: var(--fg-2);
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.55;
  min-height: 100%;
  min-height: 100dvh;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Selection carries the brand quietly. */
::selection { background: rgba(0, 215, 215, 0.28); color: var(--fg); }

/* Focus is never invisible. Domain files add :focus-visible rings on their
   controls; this is the floor for anything they miss. */
:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--radius-sm);
}

.ocean-surface {
  display: flex;
  flex-direction: column;
  height: 100%;
  height: 100dvh;
  width: 100%;
  max-width: var(--shell-max);
  min-width: 0;
  margin: 0 auto;
  padding: env(safe-area-inset-top) env(safe-area-inset-right)
           env(safe-area-inset-bottom) env(safe-area-inset-left);
}

/* ── Pointer light: faint aqua specular that follows the cursor ─── */
/* OPT-IN via the `ocean-lit` class. A single root mousemove listener
   (crates/ocean-surface-ui/src/app.rs) writes --pointer-x / --pointer-y
   onto document.documentElement as VIEWPORT percentages (clientX /
   innerWidth * 100). This ::after overlay paints a radial specular at
   that point so opted-in surfaces read as catching one overhead light.

   Tracking approach: `background-attachment: fixed` makes the gradient
   position resolve against the VIEWPORT (where the pointer is), not the
   element box — so the highlight tracks the cursor as it crosses the
   surface, while the ::after clips the paint to the element. The fixed
   overlay alternative is rejected: a position:fixed ::after escapes the
   element's overflow clip and would spill across the whole viewport.

   No effect on touch (hover gate) or reduced-motion (killed outright).
   --pointer-light / --pointer-light-mid are faint tokens by design —
   the wide radius + mid stop keep the specular shoulder invisible. */
.ocean-lit { position: relative; }
.ocean-lit::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(
    320px circle at var(--pointer-x) var(--pointer-y),
    var(--pointer-light),
    var(--pointer-light-mid) 45%,
    transparent 74%
  );
  background-attachment: fixed;
  opacity: 0;
  transition: opacity var(--dur-slow) var(--ease-tide);
}
@media (hover: hover) {
  .ocean-lit:hover::after { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .ocean-lit::after { display: none; }
}

