text:
/* Header shell ----------------------------------------------------------- */
.ocean-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-sizing: border-box;
  min-height: 56px;
  padding: 0 16px;
  background: var(--bg-raised);
  box-shadow:
    inset 0 1px 0 var(--specular-soft),   /* top-edge light */
    0 1px 0 var(--border),                /* crisp bottom seam */
    var(--shadow-sm);                     /* soft drop over the transcript */
}

/* Desktop (Tauri overlay titlebar): the header IS the titlebar — native
   traffic lights float over its left edge, so pad the brand clear of them.
   `.is-titlebar` is set on the app root only inside the Tauri shell. */
.is-titlebar .ocean-header {
  padding-left: var(--titlebar-inset);
}

/* Native chrome spans the actual window even when the readable product shell
   is capped at --shell-max. Without this, wide collapsed-workspace windows
   strand the overflow and workspace controls at the shell edge and leave a
   dead titlebar strip before the rounded window edge. The open workspace path
   already widens the root and intentionally ends the header at the pane. */
.ocean-surface.is-titlebar:not(.has-workspace-open) .ocean-header {
  width: 100vw;
  margin-left: calc((100% - 100vw) / 2);
  flex: 0 0 auto;
}

.ocean-header__right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

/* Brand ------------------------------------------------------------------ */
.ocean-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ocean-brand__word span:nth-child(1) { color: var(--ocean-4); }
.ocean-brand__word span:nth-child(2) { color: var(--ocean-5); }
.ocean-brand__word span:nth-child(3) { color: var(--ocean-6); }
.ocean-brand__word span:nth-child(4) { color: var(--ocean-7); }
.ocean-brand__word span:nth-child(5) { color: var(--ocean-8); }

/* Slow solid-color shimmer across the header wordmark letters. Each span
   keeps its ramp color (--letter-fill) and eases toward --letter-shimmer;
   never gradient-clip text. */
.ocean-brand__word span:nth-child(1) { --letter-fill: var(--ocean-4); }
.ocean-brand__word span:nth-child(2) { --letter-fill: var(--ocean-5); }
.ocean-brand__word span:nth-child(3) { --letter-fill: var(--ocean-6); }
.ocean-brand__word span:nth-child(4) { --letter-fill: var(--ocean-7); }
.ocean-brand__word span:nth-child(5) { --letter-fill: var(--ocean-8); }
@media (prefers-reduced-motion: no-preference) {
  .ocean-brand__word span {
    animation: ocean-brand-shimmer 5.5s ease-in-out infinite;
  }
  .ocean-brand__word span:nth-child(1) { animation-delay: 0s; }
  .ocean-brand__word span:nth-child(2) { animation-delay: -0.55s; }
  .ocean-brand__word span:nth-child(3) { animation-delay: -1.1s; }
  .ocean-brand__word span:nth-child(4) { animation-delay: -1.65s; }
  .ocean-brand__word span:nth-child(5) { animation-delay: -2.2s; }
  @keyframes ocean-brand-shimmer {
    0%, 100% { color: var(--letter-fill); }
    40% { color: color-mix(in srgb, var(--letter-fill) 35%, var(--letter-shimmer)); }
  }
}

/* Header lockup — the mark and the wordmark side by side, vertically
   centered with a quiet gap. */
.ocean-brand .wave-badge {
  flex: none;
  font-size: 24px;
}

.ocean-brand__word {
  display: inline-flex;
  /* Brand font — the same --wm-font (Poppins) the landing reveal letters
     use; the old --mono terminal face predates the wordmark switch. */
  font-family: var(--wm-font);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.22em;
  line-height: 1;
  white-space: nowrap;
  cursor: default;
}

