  transition: background-color var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), opacity var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);
}

.ocean-thinking,
.ocean-model-override {
  height: var(--ctl-h-sm);
  max-width: 150px;
  padding: 0 24px 0 8px;
  font-size: 11px;
  color: var(--fg-3);
  background-color: transparent;
  background-position: right 6px center;
  border-color: transparent;
}

.ocean-thinking:hover,
.ocean-model-override:hover {
  color: var(--fg);
}

.ocean-thinking:hover,
.ocean-model-override:hover {
  background-color: var(--bg-elevated);
  border-color: var(--border-strong);
}

.ocean-thinking:focus-visible,
.ocean-model-override:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}

.ocean-thinking:active,
.ocean-model-override:active {
  transform: scale(0.985);
}

.ocean-thinking:disabled,
.ocean-model-override:disabled {
  color: var(--fg-4);
  opacity: 0.45;
  pointer-events: none;
}

.ocean-thinking option,
.ocean-model-override option {
  background: var(--bg-raised);
  color: var(--fg);
  font-family: var(--font);
}

/* Button controls -------------------------------------------------------- */
.ocean-sessions-trigger,
.ocean-more__btn,
.ocean-more__item,
.ocean-council-modal__close {
  appearance: none;
  box-sizing: border-box;
  font-family: var(--font);
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), opacity var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}

.ocean-more__btn {
  display: inline-grid;
  place-items: center;
  width: var(--ctl-h-sm);
  height: var(--ctl-h-sm);
  padding: 0;
  color: var(--fg-3);
  font-size: 14px;
  line-height: 1;
  background: var(--bg-elevated);
  border: none;
  border-radius: var(--radius);
  box-shadow: var(--elev-1);
}

.ocean-more__btn:hover {
  color: var(--fg);
  background: var(--bg-hover);
}

.ocean-sessions-trigger:focus-visible,
.ocean-more__btn:focus-visible,
.ocean-council-modal__close:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}

.ocean-sessions-trigger:active,
.ocean-more__btn:active {
  transform: translateY(1px);
  box-shadow: var(--pressed);
}

/* council-close isn't a raised key, so it keeps the scale dip — pressed
   inset shadow only reads as "depressed" on an elevated surface. */
.ocean-council-modal__close:active {
  transform: scale(0.985);
}

.ocean-council-modal__close:disabled {
  color: var(--fg-4);
  opacity: 0.45;
  pointer-events: none;
}

/* Header overflow (<details>): the ONE place secondary actions live.
   Council, rooms, voice mute, and extension capture are menu rows here —
   not a strip of header buttons. */
.ocean-more {
  position: relative;
  flex: 0 0 auto;
}
.ocean-more__btn {
  list-style: none;
  user-select: none;
  font-size: 16px;
  letter-spacing: 0.05em;
}
.ocean-more__btn::-webkit-details-marker { display: none; }
.ocean-more[open] .ocean-more__btn {
  color: var(--fg);
  background: var(--bg-hover);
}
.ocean-more__menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  min-width: 176px;
  padding: 4px;
  background: var(--bg-elevated);
  border: none;
  border-radius: var(--radius);
  box-shadow: var(--elev-3);
  animation: ocean-tide-rise var(--dur) var(--ease-tide) backwards;
}

/* Tidal entrance — the menu rises from 8px below the surface, the overhead
   light catching its top edge as it settles into place. The reference
   elevated panel: a lit slab, no outline, only the specular seam + drop. */
@keyframes ocean-tide-rise {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.ocean-more__item {
  display: block;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--fg-2);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}
.ocean-more__item:hover {
  background: var(--bg-hover);
  color: var(--fg);
}
.ocean-more__item:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Sessions trigger ------------------------------------------------------- */
/* The single persistent header affordance — opens the centered sessions
   modal (chat / create project / resume). A labeled button, not an icon, so
   it reads as the primary entry point the rest of the chrome orbits. */
.ocean-sessions-trigger {
  display: inline-flex;
  align-items: center;
  height: var(--ctl-h-sm);
  padding: 0 12px;
  color: var(--fg);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  background: var(--bg-elevated);
  border: none;
  border-radius: var(--radius);
  box-shadow: var(--elev-1);
}

.ocean-sessions-trigger:hover {
  background: var(--bg-hover);
}

/* Council modal ---------------------------------------------------------- */
.ocean-council-modal {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  background: var(--bg);
}

.ocean-council-modal__bar {
  display: flex;
  flex: 0 0 56px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  box-sizing: border-box;
  padding: 0 16px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border-subtle);
}

.ocean-council-modal__title {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-family: var(--font);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ocean-council-modal__close {
  display: inline-grid;
  place-items: center;
  width: var(--ctl-h-sm);
  height: var(--ctl-h-sm);
  padding: 0;
  color: var(--fg-3);
  font-size: 14px;
  line-height: 1;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius);
}

.ocean-council-modal__close:hover {
  color: var(--fg);
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
}

.ocean-council-modal__frame {
  flex: 1 1 auto;
  width: 100%;
  min-height: 0;
  border: 0;
  background: var(--bg);
}

@media (prefers-reduced-motion: reduce) {
  .ocean-browser-control__dot {
    animation: none;
    opacity: 1;
    transform: none;
  }
  .ocean-more__menu {
    animation: none;
  }
}

text:
/* Transcript surface — conversation, tool activity, and permission gates. */

/* ── Permission approval prompts ─────────────────────────────────── */
.ocean-perms {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 18px 0;
}

.ocean-perm {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  color: var(--fg-2);
  animation: ocean-perm-in var(--dur-fast) var(--ease);
}

@keyframes ocean-perm-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.ocean-perm.is-deciding {
  opacity: 0.55;
  pointer-events: none;
}

.ocean-perm__head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ocean-perm__badge {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ocean-perm__tool {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ocean-perm__reason {
  color: var(--fg-2);
  font-size: 13px;
  line-height: 1.5;
}

.ocean-perm__args {
  max-height: 168px;
  margin: 0;
  overflow: auto;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.ocean-perm__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.ocean-perm__approve,
.ocean-perm__deny {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: var(--ctl-h);
  min-width: 82px;
  padding: 0 16px;
  border-radius: var(--radius);
  font: 600 13px/1 var(--font);
  cursor: pointer;
  transition:
    background var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    filter var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-perm__approve {
  border: none;
  background: var(--accent);
  color: var(--fg-on-accent);
}

.ocean-perm__approve:hover {
  filter: brightness(1.12);
}

.ocean-perm__deny {
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  color: var(--err);
}

.ocean-perm__deny:hover {
  background: var(--err-soft);
  border-color: var(--err);
}

.ocean-perm__approve:focus-visible,
.ocean-perm__deny:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.ocean-perm__approve:active,
.ocean-perm__deny:active {
  transform: scale(0.985);
}

.ocean-perm__approve:disabled,
.ocean-perm__deny:disabled {
  opacity: 0.45;
  pointer-events: none;
}

/* ── Transcript scroll region and empty state ────────────────────── */
.transcript {
  flex: 1;
  min-width: 0;
  overflow-x: hidden;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 18px 22px;
  /* Opaque on purpose: the animated pending badge keeps this scroll
     content on its own compositor layer, and a transparent layer's blacks
     can quantize differently from the page underneath — the boundary
     rendered as a faint full-width "lighter/darker" line at the bottom of
     the content (reported twice, Chrome and Tauri/WebKit). An opaque
     background makes the whole box one consistent surface, so any layer
     edge falls on designed boundaries (header/composer), never mid-page. */
  background: var(--bg);
  color: var(--fg-2);
}

.transcript__landing {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px 16px;
  text-align: center;
}


/* ── The Ocean badge (wave-badge) ─────────────────────────────────────
   The circular brand mark, pixel-true to the reference
   (docs/assets/ocean-logo-circular-neumorphic-reference.png): a matte
   coin face darker than the page, thin rim relief, and the muted
   turquoise→blue --badge-* ramp (NOT the neon working ramp). Reusable
   anywhere a brand/loading mark is needed; `.is-spinning` churns the
   water. Wave paths repeat every 22 user units and every loop translates
   exactly one period, so the seam is invisible. */
.wave-badge {
  display: block;
  /* Shallow relief + a faint luminous aura: the coin sits ON the surface,
     barely, and breathes a little of its own light into the dark. */
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.55))
          drop-shadow(0 0 9px color-mix(in srgb, var(--badge-b2) 9%, transparent));
}

/* Rim relief: a thin machined coin edge with a faint neutral halo. Stroke
   hue + geometry are per-instance inline (the gradient id carries the
   instance uid); only the halo filter lives here. */
.wave-badge__ring {
  filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.14));
}

/* ── The measured light — gradient stops (COLORS ONLY; tokens.css owns the
   hues). Coin material (face / rim / vignette / occlusion / gloss) plus the
   six-strata depth ramp, each band a lit top lip falling to a deeper floor.
   Fills/strokes reference these through per-instance gradient ids set inline
   on the paths (icons.rs), so multiple badges never collide. */
.wave-badge__stop-face-hi { stop-color: color-mix(in srgb, var(--badge-face) 95%, white); }
.wave-badge__stop-face { stop-color: var(--badge-face); }
.wave-badge__stop-rim-hi { stop-color: color-mix(in srgb, var(--badge-rim) 72%, white); }
.wave-badge__stop-rim-lo { stop-color: color-mix(in srgb, var(--badge-rim) 72%, black); }
.wave-badge__stop-vig-in { stop-color: transparent; }
.wave-badge__stop-vig-out { stop-color: rgba(0, 0, 0, 0.55); }
.wave-badge__stop-occl-in { stop-color: transparent; }
.wave-badge__stop-occl-mid { stop-color: rgba(0, 0, 0, 0.26); }
.wave-badge__stop-occl-out { stop-color: rgba(0, 0, 0, 0.72); }
.wave-badge__stop-gloss { stop-color: var(--badge-gloss); stop-opacity: 0.15; }
.wave-badge__stop-gloss-out { stop-color: var(--badge-gloss); stop-opacity: 0; }

.wave-badge__stop-b1-hi { stop-color: color-mix(in srgb, var(--badge-b1) 82%, white); }
.wave-badge__stop-b1-lo { stop-color: color-mix(in srgb, var(--badge-b1) 88%, black); }
.wave-badge__stop-b2-hi { stop-color: color-mix(in srgb, var(--badge-b2) 84%, white); }
.wave-badge__stop-b2-lo { stop-color: color-mix(in srgb, var(--badge-b2) 88%, black); }
.wave-badge__stop-b3-hi { stop-color: color-mix(in srgb, var(--badge-b3) 86%, white); }
.wave-badge__stop-b3-lo { stop-color: color-mix(in srgb, var(--badge-b3) 88%, black); }
.wave-badge__stop-b4-hi { stop-color: color-mix(in srgb, var(--badge-b4) 88%, white); }
.wave-badge__stop-b4-lo { stop-color: color-mix(in srgb, var(--badge-b4) 88%, black); }
.wave-badge__stop-b5-hi { stop-color: color-mix(in srgb, var(--badge-b5) 88%, white); }
.wave-badge__stop-b5-lo { stop-color: color-mix(in srgb, var(--badge-b5) 86%, black); }
.wave-badge__stop-b6-hi { stop-color: color-mix(in srgb, var(--badge-b6) 86%, white); }
.wave-badge__stop-b6-lo { stop-color: color-mix(in srgb, var(--badge-b6) 72%, black); }

/* Whitecap glint (soft halo + crisp core) and the dark longitudinal splits
   between strata. Stroke widths / blur / opacity are per-instance inline
   (they scale with the compact variant); only the hue lives here. */
.wave-badge__foam-core,
.wave-badge__foam-halo { stroke: var(--badge-foam); }
.wave-badge__split { stroke: var(--badge-split); }

/* Soundings accent: expanding foam ping ring + source glint. Ring stroke
   and glint fill live in Rust rAF; only the hue is here. Static badges
   keep both at opacity 0 (default in the SVG markup). */
.wave-badge__ping-ring { stroke: var(--badge-foam); }
.wave-badge__ping-glint { fill: var(--badge-foam); }

/* ── Landing hero field — the Soundings scene owns the whole pane. The
   canvas host is absolute inset:0, so the reveal wrapper must stretch to
   the full landing box (the old 340px cap sized the retired wordmark SVG). */
.transcript__landing-reveal {
  flex: 1 1 auto;
  align-self: stretch;
  width: 100%;
  min-height: 0;
}


/* Screen-reader title; visually quiet under the banner. */
.transcript__landing-title {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.transcript__sessions-launcher {
  appearance: none;
  display: inline-flex;
  align-items: center;
  align-self: center;
  height: var(--ctl-h);
  margin-top: 4px;
  padding: 0 18px;
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
  border-radius: var(--radius);
  color: var(--fg-2);
  font-family: var(--font);
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  transition:
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.transcript__sessions-launcher:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.transcript__sessions-launcher:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.transcript__sessions-launcher:active {
  transform: scale(0.985);
}

/* ── Turns and prose blocks ──────────────────────────────────────── */
.turn {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.turn--user,
.turn--assistant {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.turn--user {
  align-items: flex-end;
}

.turn--assistant {
  align-items: flex-start;
}


.turn__body {
  min-width: 0;
  max-width: 100%;
  color: var(--fg-2);
  overflow-wrap: anywhere;
}

.turn--user .turn__body {
  max-width: min(72ch, 86%);
  padding: 10px 12px;
  background: var(--sheen-soft), var(--bg-elevated);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  color: var(--fg);
  white-space: pre-wrap;
}

.turn--assistant .turn__body {
  width: auto;
  max-width: min(74ch, 100%);
  padding: 10px 16px;
  background: var(--sheen-soft), var(--bg-raised);
  /* --bg-raised sits 4 ticks above --bg; without a drawn edge the card's
     boundary reads as accidental banding ("a gap of pure black to softer
     black"), not geometry. The hairline makes it a deliberate card — same
     idiom as .ocean-component. */
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  /* Settle/cool: when .is-streaming drops, the specular breath animation
     stops and the card's box-shadow + border-color transition back from
     the last animated frame to the cascade values below (~1.2s). */
  transition: box-shadow 1.2s ease-out, border-color 1.2s ease-out;
}

/* Status row — tide coin + label while the assistant is working.
   Appears above the streaming turn body per edgelight.js spec. */
.ocean-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 2px;
  margin-bottom: 4px;
  font-family: var(--font);
  font-size: 11px;
  font-weight: 500;
  color: var(--fg-3);
}

.ocean-status-row .wave-badge {
  font-size: 20px;
  flex-shrink: 0;
}

/* Prose sits FLUSH inside the one reply card — no nested per-message bubbles
   (the old per-`.block--text` bubble fought the card + the cognition glow). */
.turn--assistant .turn__body .block--text {
  max-width: none;
  padding: 0;
  background: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.block {
  margin: 6px 0;
}

.block--text {
  max-width: 72ch;
  padding: 12px 16px;
  background: var(--sheen-soft), var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  color: var(--fg-2);
  font-size: 14px;
  line-height: 1.6;
  text-wrap: pretty;
}

.block--text :first-child {
  margin-top: 0;
}

.block--text :last-child {
  margin-bottom: 0;
}

.block--text p,
.block--text ul,
.block--text ol {
  margin: 0.45em 0;
}

.block--text ul,
.block--text ol {
  padding-left: 1.4em;
}

.block--text a {
  color: var(--accent);
  text-decoration-color: var(--accent-soft);
  text-underline-offset: 3px;
}

.block--text a:hover {
  text-decoration-color: var(--accent);
}

.block--text h1,
.block--text h2,
.block--text h3 {
  margin: 0.75em 0 0.35em;
  color: var(--fg);
  font-weight: 600;
  line-height: 1.25;
  text-wrap: balance;
}

.block--text h1 {
  font-size: 22px;
}

.block--text h2 {
  font-size: 18px;
}

.block--text h3 {
  font-size: 15px;
}

.block--text strong {
  color: var(--fg);
  font-weight: 600;
}

.block--text code {
  padding: 0.1em 0.38em;
  background: var(--bg-well);
  border-radius: var(--radius-sm);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
}

.block--text pre {
  max-width: 100%;
  overflow-x: auto;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: var(--well);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
}

.block--text pre code {
  padding: 0;
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}

.block--text blockquote {
  margin: 0.6em 0;
  padding: 0.1em 0 0.1em 12px;
  box-shadow: inset 1px 0 0 var(--border-subtle);
  color: var(--fg-2);
}

/* ── Generic disclosure system ─────────────────────────────────────
   Rust emits .transcript-disclosure--group|--thinking|--row on the root
   wrapper. Children: __head (button), __tick, __dot, __label, __status,
   __body. State lives on the root: .is-open .is-running .is-ok .is-err */

/* ---- Wrappers ---------------------------------------------------- */
.block--thinking {
  max-width: 72ch;
}

.block--tool.drawer {
  margin: 3px 0;
}

.tool-group {
  margin: 3px 0;
}

.transcript-disclosure--group > .transcript-disclosure__body > .block--tool.drawer {
  margin: 1px 0;
}

/* ---- Head button — base ------------------------------------------ */
.transcript-disclosure__head {
  appearance: none;
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  border: 0;
  border-radius: var(--radius);
  color: var(--fg-3);
  cursor: pointer;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.transcript-disclosure__head:hover {
  background: var(--sheen-soft), var(--bg-elevated);
  color: var(--fg);
}

.transcript-disclosure__head:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.transcript-disclosure__head:active {
  transform: scale(0.985);
  box-shadow: var(--pressed);
}

/* Group variant (tool-group): taller, mono font, always raised */
.transcript-disclosure--group > .transcript-disclosure__head {
  min-height: 28px;
  padding: 4px 10px;
  background: var(--sheen-soft), var(--bg-raised);
  box-shadow: var(--elev-1);
  font-family: var(--mono);
}
.transcript-disclosure--group > .transcript-disclosure__head:hover,
.transcript-disclosure--group.is-open > .transcript-disclosure__head {
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-2);
}

/* Row variant (drawer): shorter, transparent until hover/open */
.transcript-disclosure--row > .transcript-disclosure__head {
  min-height: 24px;
  padding: 3px 8px;
  background: transparent;
  font-family: var(--mono);
}

.transcript-disclosure--row > .transcript-disclosure__head:hover,
.transcript-disclosure--row.is-open > .transcript-disclosure__head {
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-1);
}

/* Thinking variant: pill-shaped, sans font, content-width */
.transcript-disclosure--thinking > .transcript-disclosure__head {
  display: inline-flex;
  width: auto;
  max-width: 100%;
  align-self: flex-start;
  min-height: var(--ctl-h-sm);
  padding: 0 11px;
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-1);
  font: 500 12px/1 var(--font);
}

.transcript-disclosure--thinking > .transcript-disclosure__head:hover {
  background: var(--sheen-soft), var(--bg-hover);
  box-shadow: var(--elev-2);
}

.block--thinking > .transcript-disclosure__head {
  font-style: italic;
}

/* ---- Tick (chevron) ---------------------------------------------- */
.transcript-disclosure__tick {
  flex: 0 0 auto;
  width: 10px;
}

.transcript-disclosure--group.is-open > .transcript-disclosure__head .transcript-disclosure__tick,
.transcript-disclosure--row.is-open > .transcript-disclosure__head .transcript-disclosure__tick,
.transcript-disclosure--thinking.is-open > .transcript-disclosure__head .transcript-disclosure__tick {
  color: var(--accent);
}

/* ---- Dot (status indicator) -------------------------------------- */
.transcript-disclosure__dot {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: var(--fg-4);
}

.transcript-disclosure--group.is-running > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-running > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-running > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--running);
}

.transcript-disclosure--group.is-ok > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-ok > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-ok > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--ok);
}

.transcript-disclosure--group.is-err > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-err > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-err > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--err);
}

/* ---- Label ------------------------------------------------------- */
.transcript-disclosure__label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transcript-disclosure--group > .transcript-disclosure__head > .transcript-disclosure__label,
.transcript-disclosure--row > .transcript-disclosure__head > .transcript-disclosure__label {
  font-family: var(--mono);
}

/* ---- Status ------------------------------------------------------ */
.transcript-disclosure__status {
  flex: 0 0 auto;
  color: var(--fg-3);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
}

.transcript-disclosure--group.is-running > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--row.is-running > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--thinking.is-running > .transcript-disclosure__head .transcript-disclosure__status {
  color: var(--running);
}

.transcript-disclosure--group.is-err > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--row.is-err > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--thinking.is-err > .transcript-disclosure__head .transcript-disclosure__status {
  color: var(--err);
}

/* ---- Body (expandable content) ----------------------------------- */
.transcript-disclosure__body {
  overflow: auto;
  animation: drawer-open var(--dur-fast) var(--ease);
}

/* Group body: flex container for nested drawers */
.transcript-disclosure--group > .transcript-disclosure__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 0;
}

/* Row body: mono code well */
.transcript-disclosure--row > .transcript-disclosure__body {
  max-height: 320px;
  margin: 4px 0 8px 20px;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: var(--well-deep);
  color: var(--fg-2);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
}

/* Thinking body: italic prose */
.transcript-disclosure--thinking > .transcript-disclosure__body {
  max-height: 320px;
  margin: 8px 0 0;
  padding: 10px 14px;
  background: var(--bg-raised);
  border-radius: var(--radius);
  box-shadow: var(--well);
  color: var(--fg-3);
  font: italic 13px/1.55 var(--font);
  white-space: pre-wrap;
}

@keyframes drawer-open {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Specular edge — live-turn signal (replaces the old streaming glow).
   Top-edge light turns aqua via --specular-live while .is-streaming;
   6s breath (alpha 0.05→0.16), border warms faintly (0.06→0.11).
   Settle/cool over ~1.2s when .is-streaming is removed. Pure CSS —
   no canvas or JS. The base .turn__body carries a matching transition
   so the edge fades back to neutral when the streaming class drops. */
@keyframes ocean-specular-breath {
  0%, 100% {
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 1px 2px rgba(0, 0, 0, 0.50);
    border-color: rgba(255, 255, 255, 0.06);
  }
  50% {
    box-shadow: inset 0 1px 0 var(--specular-live), 0 1px 2px rgba(0, 0, 0, 0.50);
    border-color: rgba(95, 255, 255, 0.11);
  }
}

.turn--assistant.is-streaming .turn__body {
  animation: ocean-specular-breath 6s ease-in-out infinite;
}

/* Newly-mounted turns materialize from just below the surface — a short
   opacity + 2px rise (the rise-from-depth tide). Gated on .turn.is-new,
   which Rust emits ONLY on turns appended mid-stream; hydrated history never
   carries it, so this never fires on page-load/restore. */
@keyframes ocean-turn-materialize {
  from { opacity: 0; transform: translateY(2px); }
  to   { opacity: 1; transform: translateY(0); }
}

.turn.is-new {
  animation: ocean-turn-materialize var(--dur-fast) var(--ease-tide) both;
}

/* ── Rich components inside assistant turn body — flat outer roots ──
   The turn body is THE card; nested .component-* wrappers sit flush. Genuine
   inner wells/cards keep their elevation; form, semantic callout tint, and
   interactive confirm distinction are preserved. */
.turn--assistant .turn__body .component-kanban,
.turn--assistant .turn__body .component-table,
.turn--assistant .turn__body .component-progress,
.turn--assistant .turn__body .component-markdown,
.turn--assistant .turn__body .component-dashboard,
.turn--assistant .turn__body .component-chart,
.turn--assistant .turn__body .component-timeline,
.turn--assistant .turn__body .component-stats,
.turn--assistant .turn__body .component-filetree,
.turn--assistant .turn__body .component-diff,
.turn--assistant .turn__body .component-code,
.turn--assistant .turn__body .component-gallery,
.turn--assistant .turn__body .block--component-unknown {
  background: none;
  box-shadow: none;
  border-radius: 0;
  padding: 0;
}

/* ── Compact containment — large components scroll locally at 380px ──
   Dashboards, kanbans, maps, videos and disclosure bodies stay within the
   turn without pushing page overflow. */
.turn--assistant .turn__body .component-dashboard,
.turn--assistant .turn__body .kanban-columns,
.turn--assistant .turn__body .block--map,
.turn--assistant .turn__body .block--video,
.turn--assistant .turn__body .transcript-disclosure__body {
  max-height: 380px;
  overflow: auto;
}


/* ── Markdown tables inside text blocks ──────────────────────────── */
.block--text table {
  display: block;
  width: 100%;
  max-width: 100%;
  margin: 10px 0;
  overflow-x: auto;
  border-collapse: collapse;
  color: var(--fg-2);
  font-size: 13px;
  line-height: 1.45;
}

.block--text th,
.block--text td {
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  text-align: left;
  vertical-align: top;
}

.block--text th {
  background: var(--bg-elevated);
  color: var(--fg-3);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.block--text td {
  color: var(--fg-2);
}



@media (prefers-reduced-motion: reduce) {
  .ocean-perm,
  .transcript-disclosure__body,
  .turn.is-new,
  .turn--assistant.is-streaming .turn__body {
    animation: none;
  }

  .ocean-perm__approve,
  .ocean-perm__deny,
  .transcript-disclosure__head,
  .turn--assistant .turn__body {
    transition: none;
  }

  /* Landing hero + thinking plate render a single settled GL frame in Rust;
     no CSS motion to kill beyond the shared rules above. */
}

/* ── Soundings hero + thinking plate ─────────────────────────────────
   Geometry/motion live in Rust WebGL (loader.rs); colors arrive as shader
   uniforms read from the tokens above. The thinking plate keeps a quiet
   framed slot in the pending gap. */
.soundings-thinking {
  display: flex;
  padding: 6px 0 12px;
  margin-left: 14px;
}

/* ── Full-glass landing — the reveal's water floods the whole pane ────
   The scene svg overflows its centered box (water paths span far beyond
   the 600×600 viewBox); the landing clips it at the pane edges, reading
   as a glass filled up to the orb. */
.transcript__landing {
  position: relative;
  justify-content: center;
  min-height: 100%;
  overflow: hidden;
}

.transcript__landing-reveal {
  position: relative;
}

.transcript__landing-reveal .soundings-landing canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.ocean-reveal {
  overflow: visible;
  /* No drop-shadow here: a filter would rasterize the full-bleed water's
     ink overflow every frame (huge layer, mobile jank). */
  filter: none;
}

/* Sessions launcher — submerged in the scene's water zone. Surfaces when
   the rAF wavefront crosses its spot (SoundingsLanding stamps
   `data-flooded` on its host div — no hardcoded delay). */
.transcript__landing-reveal .transcript__sessions-launcher {
  position: absolute;
  left: 50%;
  top: 75%;
  transform: translateX(-50%);
  margin-top: 0;
  z-index: 1;
  color: var(--water-crest);
  background: color-mix(in srgb, var(--water-mid) 32%, transparent);
  border: 1px solid color-mix(in srgb, var(--water-crest-soft) 30%, transparent);
  box-shadow: none;
  backdrop-filter: blur(2px);
}

.transcript__landing-reveal .transcript__sessions-launcher:hover {
  background: color-mix(in srgb, var(--water-mid) 50%, transparent);
  color: var(--badge-foam);
}

@media (prefers-reduced-motion: no-preference) {
  .transcript__landing-reveal .transcript__sessions-launcher {
    opacity: 0;
    transform: translateX(-50%) translateY(10px);
    transition: opacity 0.7s ease-out, transform 0.7s ease-out;
    pointer-events: none;
  }

  .transcript__landing-reveal [data-flooded] ~ .transcript__sessions-launcher {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
    pointer-events: auto;
  }
}

content.text:
/* Transcript surface — conversation, tool activity, and permission gates. */

/* ── Permission approval prompts ─────────────────────────────────── */
.ocean-perms {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 18px 0;
}

.ocean-perm {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  color: var(--fg-2);
  animation: ocean-perm-in var(--dur-fast) var(--ease);
}

@keyframes ocean-perm-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.ocean-perm.is-deciding {
  opacity: 0.55;
  pointer-events: none;
}

.ocean-perm__head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ocean-perm__badge {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ocean-perm__tool {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ocean-perm__reason {
  color: var(--fg-2);
  font-size: 13px;
  line-height: 1.5;
}

.ocean-perm__args {
  max-height: 168px;
  margin: 0;
  overflow: auto;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.ocean-perm__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.ocean-perm__approve,
.ocean-perm__deny {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: var(--ctl-h);
  min-width: 82px;
  padding: 0 16px;
  border-radius: var(--radius);
  font: 600 13px/1 var(--font);
  cursor: pointer;
  transition:
    background var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    filter var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-perm__approve {
  border: none;
  background: var(--accent);
  color: var(--fg-on-accent);
}

.ocean-perm__approve:hover {
  filter: brightness(1.12);
}

.ocean-perm__deny {
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  color: var(--err);
}

.ocean-perm__deny:hover {
  background: var(--err-soft);
  border-color: var(--err);
}

.ocean-perm__approve:focus-visible,
.ocean-perm__deny:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.ocean-perm__approve:active,
.ocean-perm__deny:active {
  transform: scale(0.985);
}

.ocean-perm__approve:disabled,
.ocean-perm__deny:disabled {
  opacity: 0.45;
  pointer-events: none;
}

/* ── Transcript scroll region and empty state ────────────────────── */
.transcript {
  flex: 1;
  min-width: 0;
  overflow-x: hidden;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 18px 22px;
  /* Opaque on purpose: the animated pending badge keeps this scroll
     content on its own compositor layer, and a transparent layer's blacks
     can quantize differently from the page underneath — the boundary
     rendered as a faint full-width "lighter/darker" line at the bottom of
     the content (reported twice, Chrome and Tauri/WebKit). An opaque
     background makes the whole box one consistent surface, so any layer
     edge falls on designed boundaries (header/composer), never mid-page. */
  background: var(--bg);
  color: var(--fg-2);
}

.transcript__landing {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px 16px;
  text-align: center;
}


/* ── The Ocean badge (wave-badge) ─────────────────────────────────────
   The circular brand mark, pixel-true to the reference
   (docs/assets/ocean-logo-circular-neumorphic-reference.png): a matte
   coin face darker than the page, thin rim relief, and the muted
   turquoise→blue --badge-* ramp (NOT the neon working ramp). Reusable
   anywhere a brand/loading mark is needed; `.is-spinning` churns the
   water. Wave paths repeat every 22 user units and every loop translates
   exactly one period, so the seam is invisible. */
.wave-badge {
  display: block;
  /* Shallow relief + a faint luminous aura: the coin sits ON the surface,
     barely, and breathes a little of its own light into the dark. */
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.55))
          drop-shadow(0 0 9px color-mix(in srgb, var(--badge-b2) 9%, transparent));
}

/* Rim relief: a thin machined coin edge with a faint neutral halo. Stroke
   hue + geometry are per-instance inline (the gradient id carries the
   instance uid); only the halo filter lives here. */
.wave-badge__ring {
  filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.14));
}

/* ── The measured light — gradient stops (COLORS ONLY; tokens.css owns the
   hues). Coin material (face / rim / vignette / occlusion / gloss) plus the
   six-strata depth ramp, each band a lit top lip falling to a deeper floor.
   Fills/strokes reference these through per-instance gradient ids set inline
   on the paths (icons.rs), so multiple badges never collide. */
.wave-badge__stop-face-hi { stop-color: color-mix(in srgb, var(--badge-face) 95%, white); }
.wave-badge__stop-face { stop-color: var(--badge-face); }
.wave-badge__stop-rim-hi { stop-color: color-mix(in srgb, var(--badge-rim) 72%, white); }
.wave-badge__stop-rim-lo { stop-color: color-mix(in srgb, var(--badge-rim) 72%, black); }
.wave-badge__stop-vig-in { stop-color: transparent; }
.wave-badge__stop-vig-out { stop-color: rgba(0, 0, 0, 0.55); }
.wave-badge__stop-occl-in { stop-color: transparent; }
.wave-badge__stop-occl-mid { stop-color: rgba(0, 0, 0, 0.26); }
.wave-badge__stop-occl-out { stop-color: rgba(0, 0, 0, 0.72); }
.wave-badge__stop-gloss { stop-color: var(--badge-gloss); stop-opacity: 0.15; }
.wave-badge__stop-gloss-out { stop-color: var(--badge-gloss); stop-opacity: 0; }

.wave-badge__stop-b1-hi { stop-color: color-mix(in srgb, var(--badge-b1) 82%, white); }
.wave-badge__stop-b1-lo { stop-color: color-mix(in srgb, var(--badge-b1) 88%, black); }
.wave-badge__stop-b2-hi { stop-color: color-mix(in srgb, var(--badge-b2) 84%, white); }
.wave-badge__stop-b2-lo { stop-color: color-mix(in srgb, var(--badge-b2) 88%, black); }
.wave-badge__stop-b3-hi { stop-color: color-mix(in srgb, var(--badge-b3) 86%, white); }
.wave-badge__stop-b3-lo { stop-color: color-mix(in srgb, var(--badge-b3) 88%, black); }
.wave-badge__stop-b4-hi { stop-color: color-mix(in srgb, var(--badge-b4) 88%, white); }
.wave-badge__stop-b4-lo { stop-color: color-mix(in srgb, var(--badge-b4) 88%, black); }
.wave-badge__stop-b5-hi { stop-color: color-mix(in srgb, var(--badge-b5) 88%, white); }
.wave-badge__stop-b5-lo { stop-color: color-mix(in srgb, var(--badge-b5) 86%, black); }
.wave-badge__stop-b6-hi { stop-color: color-mix(in srgb, var(--badge-b6) 86%, white); }
.wave-badge__stop-b6-lo { stop-color: color-mix(in srgb, var(--badge-b6) 72%, black); }

/* Whitecap glint (soft halo + crisp core) and the dark longitudinal splits
   between strata. Stroke widths / blur / opacity are per-instance inline
   (they scale with the compact variant); only the hue lives here. */
.wave-badge__foam-core,
.wave-badge__foam-halo { stroke: var(--badge-foam); }
.wave-badge__split { stroke: var(--badge-split); }

/* Soundings accent: expanding foam ping ring + source glint. Ring stroke
   and glint fill live in Rust rAF; only the hue is here. Static badges
   keep both at opacity 0 (default in the SVG markup). */
.wave-badge__ping-ring { stroke: var(--badge-foam); }
.wave-badge__ping-glint { fill: var(--badge-foam); }

/* ── Landing hero field — the Soundings scene owns the whole pane. The
   canvas host is absolute inset:0, so the reveal wrapper must stretch to
   the full landing box (the old 340px cap sized the retired wordmark SVG). */
.transcript__landing-reveal {
  flex: 1 1 auto;
  align-self: stretch;
  width: 100%;
  min-height: 0;
}


/* Screen-reader title; visually quiet under the banner. */
.transcript__landing-title {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.transcript__sessions-launcher {
  appearance: none;
  display: inline-flex;
  align-items: center;
  align-self: center;
  height: var(--ctl-h);
  margin-top: 4px;
  padding: 0 18px;
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
  border-radius: var(--radius);
  color: var(--fg-2);
  font-family: var(--font);
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  transition:
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.transcript__sessions-launcher:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.transcript__sessions-launcher:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.transcript__sessions-launcher:active {
  transform: scale(0.985);
}

/* ── Turns and prose blocks ──────────────────────────────────────── */
.turn {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.turn--user,
.turn--assistant {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.turn--user {
  align-items: flex-end;
}

.turn--assistant {
  align-items: flex-start;
}


.turn__body {
  min-width: 0;
  max-width: 100%;
  color: var(--fg-2);
  overflow-wrap: anywhere;
}

.turn--user .turn__body {
  max-width: min(72ch, 86%);
  padding: 10px 12px;
  background: var(--sheen-soft), var(--bg-elevated);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  color: var(--fg);
  white-space: pre-wrap;
}

.turn--assistant .turn__body {
  width: auto;
  max-width: min(74ch, 100%);
  padding: 10px 16px;
  background: var(--sheen-soft), var(--bg-raised);
  /* --bg-raised sits 4 ticks above --bg; without a drawn edge the card's
     boundary reads as accidental banding ("a gap of pure black to softer
     black"), not geometry. The hairline makes it a deliberate card — same
     idiom as .ocean-component. */
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  /* Settle/cool: when .is-streaming drops, the specular breath animation
     stops and the card's box-shadow + border-color transition back from
     the last animated frame to the cascade values below (~1.2s). */
  transition: box-shadow 1.2s ease-out, border-color 1.2s ease-out;
}

/* Status row — tide coin + label while the assistant is working.
   Appears above the streaming turn body per edgelight.js spec. */
.ocean-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 2px;
  margin-bottom: 4px;
  font-family: var(--font);
  font-size: 11px;
  font-weight: 500;
  color: var(--fg-3);
}

.ocean-status-row .wave-badge {
  font-size: 20px;
  flex-shrink: 0;
}

/* Prose sits FLUSH inside the one reply card — no nested per-message bubbles
   (the old per-`.block--text` bubble fought the card + the cognition glow). */
.turn--assistant .turn__body .block--text {
  max-width: none;
  padding: 0;
  background: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.block {
  margin: 6px 0;
}

.block--text {
  max-width: 72ch;
  padding: 12px 16px;
  background: var(--sheen-soft), var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-1);
  color: var(--fg-2);
  font-size: 14px;
  line-height: 1.6;
  text-wrap: pretty;
}

.block--text :first-child {
  margin-top: 0;
}

.block--text :last-child {
  margin-bottom: 0;
}

.block--text p,
.block--text ul,
.block--text ol {
  margin: 0.45em 0;
}

.block--text ul,
.block--text ol {
  padding-left: 1.4em;
}

.block--text a {
  color: var(--accent);
  text-decoration-color: var(--accent-soft);
  text-underline-offset: 3px;
}

.block--text a:hover {
  text-decoration-color: var(--accent);
}

.block--text h1,
.block--text h2,
.block--text h3 {
  margin: 0.75em 0 0.35em;
  color: var(--fg);
  font-weight: 600;
  line-height: 1.25;
  text-wrap: balance;
}

.block--text h1 {
  font-size: 22px;
}

.block--text h2 {
  font-size: 18px;
}

.block--text h3 {
  font-size: 15px;
}

.block--text strong {
  color: var(--fg);
  font-weight: 600;
}

.block--text code {
  padding: 0.1em 0.38em;
  background: var(--bg-well);
  border-radius: var(--radius-sm);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
}

.block--text pre {
  max-width: 100%;
  overflow-x: auto;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: var(--well);
  color: var(--fg);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
}

.block--text pre code {
  padding: 0;
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}

.block--text blockquote {
  margin: 0.6em 0;
  padding: 0.1em 0 0.1em 12px;
  box-shadow: inset 1px 0 0 var(--border-subtle);
  color: var(--fg-2);
}

/* ── Generic disclosure system ─────────────────────────────────────
   Rust emits .transcript-disclosure--group|--thinking|--row on the root
   wrapper. Children: __head (button), __tick, __dot, __label, __status,
   __body. State lives on the root: .is-open .is-running .is-ok .is-err */

/* ---- Wrappers ---------------------------------------------------- */
.block--thinking {
  max-width: 72ch;
}

.block--tool.drawer {
  margin: 3px 0;
}

.tool-group {
  margin: 3px 0;
}

.transcript-disclosure--group > .transcript-disclosure__body > .block--tool.drawer {
  margin: 1px 0;
}

/* ---- Head button — base ------------------------------------------ */
.transcript-disclosure__head {
  appearance: none;
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  border: 0;
  border-radius: var(--radius);
  color: var(--fg-3);
  cursor: pointer;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.transcript-disclosure__head:hover {
  background: var(--sheen-soft), var(--bg-elevated);
  color: var(--fg);
}

.transcript-disclosure__head:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.transcript-disclosure__head:active {
  transform: scale(0.985);
  box-shadow: var(--pressed);
}

/* Group variant (tool-group): taller, mono font, always raised */
.transcript-disclosure--group > .transcript-disclosure__head {
  min-height: 28px;
  padding: 4px 10px;
  background: var(--sheen-soft), var(--bg-raised);
  box-shadow: var(--elev-1);
  font-family: var(--mono);
}
.transcript-disclosure--group > .transcript-disclosure__head:hover,
.transcript-disclosure--group.is-open > .transcript-disclosure__head {
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-2);
}

/* Row variant (drawer): shorter, transparent until hover/open */
.transcript-disclosure--row > .transcript-disclosure__head {
  min-height: 24px;
  padding: 3px 8px;
  background: transparent;
  font-family: var(--mono);
}

.transcript-disclosure--row > .transcript-disclosure__head:hover,
.transcript-disclosure--row.is-open > .transcript-disclosure__head {
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-1);
}

/* Thinking variant: pill-shaped, sans font, content-width */
.transcript-disclosure--thinking > .transcript-disclosure__head {
  display: inline-flex;
  width: auto;
  max-width: 100%;
  align-self: flex-start;
  min-height: var(--ctl-h-sm);
  padding: 0 11px;
  background: var(--sheen-soft), var(--bg-elevated);
  box-shadow: var(--elev-1);
  font: 500 12px/1 var(--font);
}

.transcript-disclosure--thinking > .transcript-disclosure__head:hover {
  background: var(--sheen-soft), var(--bg-hover);
  box-shadow: var(--elev-2);
}

.block--thinking > .transcript-disclosure__head {
  font-style: italic;
}

/* ---- Tick (chevron) ---------------------------------------------- */
.transcript-disclosure__tick {
  flex: 0 0 auto;
  width: 10px;
}

.transcript-disclosure--group.is-open > .transcript-disclosure__head .transcript-disclosure__tick,
.transcript-disclosure--row.is-open > .transcript-disclosure__head .transcript-disclosure__tick,
.transcript-disclosure--thinking.is-open > .transcript-disclosure__head .transcript-disclosure__tick {
  color: var(--accent);
}

/* ---- Dot (status indicator) -------------------------------------- */
.transcript-disclosure__dot {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: var(--fg-4);
}

.transcript-disclosure--group.is-running > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-running > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-running > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--running);
}

.transcript-disclosure--group.is-ok > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-ok > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-ok > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--ok);
}

.transcript-disclosure--group.is-err > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--row.is-err > .transcript-disclosure__head .transcript-disclosure__dot,
.transcript-disclosure--thinking.is-err > .transcript-disclosure__head .transcript-disclosure__dot {
  background: var(--err);
}

/* ---- Label ------------------------------------------------------- */
.transcript-disclosure__label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transcript-disclosure--group > .transcript-disclosure__head > .transcript-disclosure__label,
.transcript-disclosure--row > .transcript-disclosure__head > .transcript-disclosure__label {
  font-family: var(--mono);
}

/* ---- Status ------------------------------------------------------ */
.transcript-disclosure__status {
  flex: 0 0 auto;
  color: var(--fg-3);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
}

.transcript-disclosure--group.is-running > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--row.is-running > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--thinking.is-running > .transcript-disclosure__head .transcript-disclosure__status {
  color: var(--running);
}

.transcript-disclosure--group.is-err > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--row.is-err > .transcript-disclosure__head .transcript-disclosure__status,
.transcript-disclosure--thinking.is-err > .transcript-disclosure__head .transcript-disclosure__status {
  color: var(--err);
}

/* ---- Body (expandable content) ----------------------------------- */
.transcript-disclosure__body {
  overflow: auto;
  animation: drawer-open var(--dur-fast) var(--ease);
}

/* Group body: flex container for nested drawers */
.transcript-disclosure--group > .transcript-disclosure__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 0;
}

/* Row body: mono code well */
.transcript-disclosure--row > .transcript-disclosure__body {
  max-height: 320px;
  margin: 4px 0 8px 20px;
  padding: 10px 12px;
  background: var(--bg-well);
  border-radius: var(--radius);
  box-shadow: var(--well-deep);
  color: var(--fg-2);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
}

/* Thinking body: italic prose */
.transcript-disclosure--thinking > .transcript-disclosure__body {
  max-height: 320px;
  margin: 8px 0 0;
  padding: 10px 14px;
  background: var(--bg-raised);
  border-radius: var(--radius);
  box-shadow: var(--well);
  color: var(--fg-3);
  font: italic 13px/1.55 var(--font);
  white-space: pre-wrap;
}

@keyframes drawer-open {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Specular edge — live-turn signal (replaces the old streaming glow).
   Top-edge light turns aqua via --specular-live while .is-streaming;
   6s breath (alpha 0.05→0.16), border warms faintly (0.06→0.11).
   Settle/cool over ~1.2s when .is-streaming is removed. Pure CSS —
   no canvas or JS. The base .turn__body carries a matching transition
   so the edge fades back to neutral when the streaming class drops. */
@keyframes ocean-specular-breath {
  0%, 100% {
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 1px 2px rgba(0, 0, 0, 0.50);
    border-color: rgba(255, 255, 255, 0.06);
  }
  50% {
    box-shadow: inset 0 1px 0 var(--specular-live), 0 1px 2px rgba(0, 0, 0, 0.50);
    border-color: rgba(95, 255, 255, 0.11);
  }
}

.turn--assistant.is-streaming .turn__body {
  animation: ocean-specular-breath 6s ease-in-out infinite;
}

/* Newly-mounted turns materialize from just below the surface — a short
   opacity + 2px rise (the rise-from-depth tide). Gated on .turn.is-new,
   which Rust emits ONLY on turns appended mid-stream; hydrated history never
   carries it, so this never fires on page-load/restore. */
@keyframes ocean-turn-materialize {
  from { opacity: 0; transform: translateY(2px); }
  to   { opacity: 1; transform: translateY(0); }
}

.turn.is-new {
  animation: ocean-turn-materialize var(--dur-fast) var(--ease-tide) both;
}

/* ── Rich components inside assistant turn body — flat outer roots ──
   The turn body is THE card; nested .component-* wrappers sit flush. Genuine
   inner wells/cards keep their elevation; form, semantic callout tint, and
   interactive confirm distinction are preserved. */
.turn--assistant .turn__body .component-kanban,
.turn--assistant .turn__body .component-table,
.turn--assistant .turn__body .component-progress,
.turn--assistant .turn__body .component-markdown,
.turn--assistant .turn__body .component-dashboard,
.turn--assistant .turn__body .component-chart,
.turn--assistant .turn__body .component-timeline,
.turn--assistant .turn__body .component-stats,
.turn--assistant .turn__body .component-filetree,
.turn--assistant .turn__body .component-diff,
.turn--assistant .turn__body .component-code,
.turn--assistant .turn__body .component-gallery,
.turn--assistant .turn__body .block--component-unknown {
  background: none;
  box-shadow: none;
  border-radius: 0;
  padding: 0;
}

/* ── Compact containment — large components scroll locally at 380px ──
   Dashboards, kanbans, maps, videos and disclosure bodies stay within the
   turn without pushing page overflow. */
.turn--assistant .turn__body .component-dashboard,
.turn--assistant .turn__body .kanban-columns,
.turn--assistant .turn__body .block--map,
.turn--assistant .turn__body .block--video,
.turn--assistant .turn__body .transcript-disclosure__body {
  max-height: 380px;
  overflow: auto;
}


/* ── Markdown tables inside text blocks ──────────────────────────── */
.block--text table {
  display: block;
  width: 100%;
  max-width: 100%;
  margin: 10px 0;
  overflow-x: auto;
  border-collapse: collapse;
  color: var(--fg-2);
  font-size: 13px;
  line-height: 1.45;
}

.block--text th,
.block--text td {
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  text-align: left;
  vertical-align: top;
}

.block--text th {
  background: var(--bg-elevated);
  color: var(--fg-3);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.block--text td {
  color: var(--fg-2);
}



@media (prefers-reduced-motion: reduce) {
  .ocean-perm,
  .transcript-disclosure__body,
  .turn.is-new,
  .turn--assistant.is-streaming .turn__body {
    animation: none;
  }

  .ocean-perm__approve,
  .ocean-perm__deny,
  .transcript-disclosure__head,
  .turn--assistant .turn__body {
    transition: none;
  }

  /* Landing hero + thinking plate render a single settled GL frame in Rust;
     no CSS motion to kill beyond the shared rules above. */
}

/* ── Soundings hero + thinking plate ─────────────────────────────────
   Geometry/motion live in Rust WebGL (loader.rs); colors arrive as shader
   uniforms read from the tokens above. The thinking plate keeps a quiet
   framed slot in the pending gap. */
.soundings-thinking {
  display: flex;
  padding: 6px 0 12px;
  margin-left: 14px;
}

/* ── Full-glass landing — the reveal's water floods the whole pane ────
   The scene svg overflows its centered box (water paths span far beyond
   the 600×600 viewBox); the landing clips it at the pane edges, reading
   as a glass filled up to the orb. */
.transcript__landing {
  position: relative;
  justify-content: center;
  min-height: 100%;
  overflow: hidden;
}

.transcript__landing-reveal {
  position: relative;
}

.transcript__landing-reveal .soundings-landing canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.ocean-reveal {
  overflow: visible;
  /* No drop-shadow here: a filter would rasterize the full-bleed water's
     ink overflow every frame (huge layer, mobile jank). */
  filter: none;
}

/* Sessions launcher — submerged in the scene's water zone. Surfaces when
   the rAF wavefront crosses its spot (SoundingsLanding stamps
   `data-flooded` on its host div — no hardcoded delay). */
.transcript__landing-reveal .transcript__sessions-launcher {
  position: absolute;
  left: 50%;
  top: 75%;
  transform: translateX(-50%);
  margin-top: 0;
  z-index: 1;
  color: var(--water-crest);
  background: color-mix(in srgb, var(--water-mid) 32%, transparent);
  border: 1px solid color-mix(in srgb, var(--water-crest-soft) 30%, transparent);
  box-shadow: none;
  backdrop-filter: blur(2px);
}

.transcript__landing-reveal .transcript__sessions-launcher:hover {
  background: color-mix(in srgb, var(--water-mid) 50%, transparent);
  color: var(--badge-foam);
}

@media (prefers-reduced-motion: no-preference) {
  .transcript__landing-reveal .transcript__sessions-launcher {
    opacity: 0;
    transform: translateX(-50%) translateY(10px);
    transition: opacity 0.7s ease-out, transform 0.7s ease-out;
    pointer-events: none;
  }

  .transcript__landing-reveal [data-flooded] ~ .transcript__sessions-launcher {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
    pointer-events: auto;
  }
}

text:
/* ─── Composer dock + voice input ───────────────────────────────────────────
   Visual contract: product-register controls from docs/OCEAN_WEB_SURFACE_DESIGN.md.
   Rust owns behavior and class names; this file only skins the emitted surface.
   ───────────────────────────────────────────────────────────────────────── */

/* One compact dock card. The writing row owns the full width; the lower
   toolbar keeps voice, turn controls, and the single action slot aligned.
   The FORM is the only framed surface and owns the focus ring. */
.ocean-composer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "input input input"
    "orb controls action";
  align-items: center;
  column-gap: 8px;
  row-gap: 4px;
  margin: 8px 18px 12px;
  padding: 8px 12px;
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
  box-shadow: var(--elev-2);
  transition: box-shadow var(--dur) var(--ease-tide);
}
.ocean-composer:focus-within {
  box-shadow: var(--elev-2), var(--focus-ring);
}

/* ── voice orb ─────────────────────────────────────────────────────────── */

.voice-wrap {
  position: relative;
  grid-area: orb;
  display: flex;
  flex: 0 0 auto;
  flex-direction: row;
  gap: 2px;
  align-items: center;
  align-self: center;
}

.voice-orb {
  appearance: none;
  display: grid;
  width: var(--ctl-h);
  height: var(--ctl-h);
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--bg-elevated);
  color: var(--fg-3);
  font: inherit;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
  transition:
    transform var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.voice-orb:hover {
  border-color: var(--border-strong);
  background: var(--bg-hover);
  color: var(--fg);
}

.voice-orb:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-orb:active {
  transform: scale(0.985);
}

.voice-orb.is-disabled,
.voice-orb:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.voice-orb__glyph {
  display: inline-flex;
  pointer-events: none;
  color: currentColor;
}

.voice-orb__glyph .icon,
.voice-orb__glyph svg {
  width: 18px;
  height: 18px;
}

.voice-orb.is-recording {
  border-color: transparent;
  background: var(--accent);
  color: var(--fg-on-accent);
  box-shadow: var(--glow-brand);
  animation: voice-pulse 1.35s var(--ease) infinite;
}

.voice-orb.is-transcribing {
  border-color: var(--warn);
  background: var(--warn-soft);
  color: var(--warn);
  animation: voice-transcribe 1.4s var(--ease) infinite;
}

.voice-orb.is-live {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
  --voice-listen-pulse: var(--accent-soft);
  animation: voice-listen 2.4s var(--ease) infinite;
}

.voice-orb.is-live.is-capturing {
  border-color: transparent;
  background: var(--accent);
  color: var(--fg-on-accent);
  box-shadow: var(--glow-brand);
  animation: voice-pulse 1s var(--ease) infinite;
}

.voice-orb.is-live.is-transcribing {
  border-color: var(--warn);
  background: var(--warn-soft);
  color: var(--warn);
  box-shadow: none;
  animation: voice-transcribe 1.2s var(--ease) infinite;
}

/* Off is a true device-level kill switch: the orb goes quiet (no glow, no
   breathing) but stays clickable — a click reopens this menu, not the mic. */
.voice-orb.is-off {
  color: var(--fg-3);
  border-color: var(--border-subtle);
  background: var(--bg-elevated);
  box-shadow: none;
  animation: none;
}

@keyframes voice-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(0, 215, 215, 0.20), var(--glow-brand);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(0, 215, 215, 0.08), var(--glow-brand);
  }
}

@keyframes voice-listen {
  0%, 100% {
    box-shadow: 0 0 0 0 var(--voice-listen-pulse);
  }
  50% {
    box-shadow: 0 0 0 5px var(--voice-listen-pulse);
  }
}

@keyframes voice-transcribe {
  0%, 100% {
    box-shadow: 0 0 0 0 var(--warn-soft);
  }
  50% {
    box-shadow: 0 0 0 5px var(--warn-soft);
  }
}

/* ── voice mode menu ──────────────────────────────────────────────────── */
/* A popover of the three honest mic modes (off / push-to-talk / hands-free)
   anchored above the orb inside .voice-wrap (position: relative). The orb is
   the mic; a small trigger opens this menu. Rust owns the active mode and
   whether the menu is mounted — this only skins the emitted panel. */

.voice-menu {
  position: absolute;
  bottom: calc(100% + 8px);
  /* The orb sits at the composer's LEFT edge — anchor the popover's left
     to the wrap so it grows rightward over the composer, not off-viewport. */
  left: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  min-width: 224px;
  padding: 6px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--elev-3);
  animation: voice-menu-enter var(--dur-fast) var(--ease) both;
}

@keyframes voice-menu-enter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mode row — icon left, label + description stacked right. The three are
   direct children placed by grid, so source order never breaks the layout. */
.voice-menu__item {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 8px;
  row-gap: 2px;
  align-items: center;
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.voice-menu__item:hover {
  background: var(--bg-hover);
}

.voice-menu__item:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-menu__item.is-active {
  background: var(--accent-soft);
}

.voice-menu__item-icon {
  grid-row: 1 / span 2;
  grid-column: 1;
  align-self: center;
  display: inline-flex;
  font-size: 14px;
  color: var(--fg-3);
}

.voice-menu__item-icon .icon,
.voice-menu__item-icon svg {
  width: 1em;
  height: 1em;
}

.voice-menu__item.is-active .voice-menu__item-icon {
  color: var(--accent);
}

.voice-menu__item-label {
  grid-column: 2;
  grid-row: 1;
  font-size: 12px;
  line-height: 1.3;
  color: var(--fg);
}

.voice-menu__item-desc {
  grid-column: 2;
  grid-row: 2;
  font-size: 11px;
  line-height: 1.35;
  color: var(--fg-3);
}

.voice-menu__error {
  color: var(--err);
  font-size: 11px;
  line-height: 1.35;
  padding-inline: 8px;
  margin: 0;
}

/* Hr-like separator between mode rows and the spoken-replies toggle. */
.voice-menu__divider {
  height: 0;
  margin: 6px 2px;
  border: 0;
  border-top: 1px solid var(--border-subtle);
}

/* "Microphone" group label — non-interactive section header for the
   radio-group portion of the voice menu. */
.voice-menu__group-label {
  display: block;
  padding: 6px 8px 2px;
  font-size: 10px;
  line-height: 1.4;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-3);
  user-select: none;
}

/* Spoken-replies toggle — a quiet row with a trailing state dot (::after);
   is-on blooms the dot aqua to read as "replies on". */
.voice-menu__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  font-size: 12px;
  line-height: 1.3;
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.voice-menu__toggle:hover {
  background: var(--bg-hover);
}

.voice-menu__toggle:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-menu__toggle::after {
  content: "";
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: var(--border-strong);
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease);
}

.voice-menu__toggle.is-on::after {
  background: var(--accent);
  box-shadow: 0 0 6px var(--accent-soft);
}

/* Privacy footnote — small, muted, the last word on what leaves the device. */
.voice-menu__note {
  padding: 6px 8px 2px;
  font-size: 10px;
  line-height: 1.4;
  color: var(--fg-3);
}

/* ── voice trigger + live chip ────────────────────────────────────────── */
/* The trigger is a ghost chevron that opens the menu — quiet by default,
   found on hover/focus, with a 0.35 floor so touch users always reach it.
   The live chip shows only while hands-free is hot: a pulsing aqua dot. */

.voice-trigger {
  appearance: none;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--fg-3);
  font-size: 12px;
  opacity: 0.35;
  cursor: pointer;
  transition:
    opacity var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-trigger .icon,
.voice-trigger svg {
  width: 1em;
  height: 1em;
}

.voice-wrap:hover .voice-trigger,
.voice-wrap:focus-within .voice-trigger,
.voice-wrap:has(.voice-menu) .voice-trigger {
  opacity: 1;
}

.voice-trigger:hover {
  color: var(--fg);
  opacity: 1;
}

.voice-trigger:focus-visible {
  outline: none;
  opacity: 1;
  box-shadow: var(--focus-ring);
  border-radius: var(--radius-sm);
}

.voice-live-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  background: var(--bg-raised);
  color: var(--fg-2);
  font-size: 10px;
  line-height: 1;
  cursor: pointer;
  transition:
    border-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-live-chip:hover {
  border-color: var(--border-strong);
  color: var(--fg);
}

.voice-live-chip:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Pulsing dot — the hot aqua behind --glow-live (ocean-7 / --accent-bright),
   the same live family the call styles ring speaking tiles with. */
.voice-live-chip::before {
  content: "";
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--accent-bright);
  box-shadow: 0 0 6px var(--accent-soft);
  animation: voice-chip-pulse 1.4s var(--ease) infinite;
}

@keyframes voice-chip-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

/* The orb speaks through color and its tooltip; a permanent caption under
   it is knob noise. */
.voice-hint { display: none; }

/* ── text composer ────────────────────────────────────────────────────── */

.ocean-composer__input {
  grid-area: input;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 32px;
  max-height: 240px;
  overflow-y: hidden;
  padding: 4px 4px 6px;
  resize: none;
  border: none;
  border-radius: 0;
  outline: none;
  background: transparent;
  box-shadow: none;
  color: var(--fg);
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.45;
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-composer__input::placeholder {
  color: var(--fg-3);
}

.ocean-composer__input:focus,
.ocean-composer__input:focus-visible {
  outline: none;
  box-shadow: none;
}

.ocean-composer__input:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Trailing action — one circular icon slot shared by Send (idle, accent) and
   Stop (streaming, halt-red). Mutually exclusive; both live in `action`. */
.ocean-composer__send,
.ocean-composer__halt {
  grid-area: action;
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--ctl-h);      /* 34px circle */
  height: var(--ctl-h);
  padding: 0;
  font-size: 18px;          /* drives the 1em icon */
  border: none;
  border-radius: var(--radius-pill);
  cursor: pointer;
  transition:
    transform var(--dur-fast) var(--ease),
    filter var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-composer__send {
  background: var(--accent);
  box-shadow: var(--elev-1);
  color: var(--fg-on-accent);
}

.ocean-composer__send:hover {
  filter: brightness(1.12);
}

.ocean-composer__send:focus-visible {
  outline: none;
  box-shadow: var(--elev-1), var(--focus-ring);
}

.ocean-composer__send:active {
  transform: translateY(1px);
  box-shadow: var(--pressed);
}

.ocean-composer__send:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
  filter: none;
  box-shadow: none;
}

.ocean-composer__halt {
  background: var(--err-soft);
  box-shadow: var(--elev-1);
  color: var(--err);
}

.ocean-composer__halt:hover {
  filter: brightness(1.12);
}

.ocean-composer__halt:focus-visible {
  outline: none;
  box-shadow: var(--elev-1), var(--focus-ring);
}

.ocean-composer__halt:active {
  transform: translateY(1px);
  box-shadow: var(--pressed);
}

@media (prefers-reduced-motion: reduce) {
  .ocean-composer,
  .voice-orb,
  .voice-menu,
  .voice-trigger,
  .voice-live-chip,
  .ocean-composer__input,
  .ocean-composer__send,
  .ocean-composer__halt {
    transition: none;
    animation: none;
  }

  .voice-orb.is-recording,
  .voice-orb.is-transcribing,
  .voice-orb.is-live,
  .voice-orb.is-live.is-capturing,
  .voice-orb.is-live.is-transcribing {
    animation: none;
  }

  .voice-live-chip::before {
    animation: none;
  }
}

/* ── Realtime voice chat (voice phases 2/3) ──────────────────────────────
   While a voice session is connecting/live and no components are on screen
   (`.voice-chat-active` on the app root), the composer's text input, send
   button, and per-turn controls hide — kept mounted so their signals stay
   alive — and the orb takes center stage: floated above the composer,
   enlarged, its glow breathing with the live mic level (`--voice-level`,
   0..1, written by the level meter in voice/realtime.rs). Once the voice
   agent renders components (`.voice-chat-docked` replaces `-active`) the
   orb returns to its normal composer slot so they get the room. Both
   Send and Stop share the action slot and hide in this mode. These states are
   class-driven; stage Off removes them and reverts everything. */

.voice-chat-active .ocean-composer__input,
.voice-chat-active .ocean-composer__send,
.voice-chat-active .ocean-composer__halt,
.voice-chat-active .ocean-turn-controls,
.voice-chat-active .ocean-slash-menu {
  display: none;
}

.ocean-slash-menu {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(100% + 8px);
  max-height: 280px;
  overflow: auto;
  z-index: 40;
  padding: 6px;
  border-radius: var(--radius-md, 10px);
  background: var(--surface-elevated, var(--bg-elevated, #12141a));
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  box-shadow: var(--shadow-md, 0 8px 28px rgba(0,0,0,0.35));
}
.ocean-slash-menu__group + .ocean-slash-menu__group {
  margin-top: 6px;
}
.ocean-slash-menu__group-label {
  padding: 4px 8px;
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--fg-muted, #8b93a7);
}
.ocean-slash-menu__row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
  width: 100%;
  text-align: left;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--fg, #e8ecf5);
  cursor: pointer;
}
.ocean-slash-menu__row.is-selected,
.ocean-slash-menu__row:hover {
  background: var(--surface-hover, rgba(255,255,255,0.06));
}
.ocean-slash-menu__row.is-disabled {
  opacity: 0.45;
  cursor: default;
}
.ocean-slash-menu__title {
  font-size: 13px;
}
.ocean-slash-menu__alias {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
  color: var(--fg-muted, #8b93a7);
}
.ocean-slash-menu__hint {
  grid-column: 1 / -1;
  font-size: 11px;
  color: var(--fg-muted, #8b93a7);
}

.voice-chat-active .voice-wrap {
  /* Release the named grid placement: an abs-pos grid child WITH a grid-area
     uses that area as its containing block, which pinned the orb to the tiny
     orb track instead of centering over the whole composer. */
  grid-area: auto;
  position: absolute;
  left: 50%;
  bottom: calc(100% + 56px);
  transform: translateX(-50%);
  z-index: 30;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.voice-chat-active .voice-orb {
  width: 108px;
  height: 108px;
  border-radius: 50%;
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
  /* Mic-reactive breathing: scale + glow track the live level. Deliberately
     NOT transitioned — the level writes at ~60Hz and must track instantly. */
  transform: scale(calc(1 + var(--voice-level, 0) * 0.16));
  box-shadow: 0 0 calc(16px + 44px * var(--voice-level, 0)) var(--accent-soft);
  /* Promotion/dock animates size only; transform/box-shadow stay untransitioned
     so the ~60Hz level writes track instantly. Color transitions kept. */
  transition:
    width 300ms var(--ease),
    height 300ms var(--ease),
    border-color var(--dur-fast) var(--ease),
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-chat-active .voice-orb__glyph .icon,
.voice-chat-active .voice-orb__glyph svg {
  width: 44px;
  height: 44px;
}

.voice-chat-active .voice-hint {
  position: static;
  text-align: center;
  font-size: 13px;
  color: var(--fg-2);
}

@media (prefers-reduced-motion: reduce) {
  .voice-chat-active .voice-orb {
    transition: none;
    transform: none;
    box-shadow: 0 0 16px var(--accent-soft);
  }
}

content.text:
/* ─── Composer dock + voice input ───────────────────────────────────────────
   Visual contract: product-register controls from docs/OCEAN_WEB_SURFACE_DESIGN.md.
   Rust owns behavior and class names; this file only skins the emitted surface.
   ───────────────────────────────────────────────────────────────────────── */

/* One compact dock card. The writing row owns the full width; the lower
   toolbar keeps voice, turn controls, and the single action slot aligned.
   The FORM is the only framed surface and owns the focus ring. */
.ocean-composer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "input input input"
    "orb controls action";
  align-items: center;
  column-gap: 8px;
  row-gap: 4px;
  margin: 8px 18px 12px;
  padding: 8px 12px;
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
  box-shadow: var(--elev-2);
  transition: box-shadow var(--dur) var(--ease-tide);
}
.ocean-composer:focus-within {
  box-shadow: var(--elev-2), var(--focus-ring);
}

/* ── voice orb ─────────────────────────────────────────────────────────── */

.voice-wrap {
  position: relative;
  grid-area: orb;
  display: flex;
  flex: 0 0 auto;
  flex-direction: row;
  gap: 2px;
  align-items: center;
  align-self: center;
}

.voice-orb {
  appearance: none;
  display: grid;
  width: var(--ctl-h);
  height: var(--ctl-h);
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--bg-elevated);
  color: var(--fg-3);
  font: inherit;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
  transition:
    transform var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.voice-orb:hover {
  border-color: var(--border-strong);
  background: var(--bg-hover);
  color: var(--fg);
}

.voice-orb:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-orb:active {
  transform: scale(0.985);
}

.voice-orb.is-disabled,
.voice-orb:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.voice-orb__glyph {
  display: inline-flex;
  pointer-events: none;
  color: currentColor;
}

.voice-orb__glyph .icon,
.voice-orb__glyph svg {
  width: 18px;
  height: 18px;
}

.voice-orb.is-recording {
  border-color: transparent;
  background: var(--accent);
  color: var(--fg-on-accent);
  box-shadow: var(--glow-brand);
  animation: voice-pulse 1.35s var(--ease) infinite;
}

.voice-orb.is-transcribing {
  border-color: var(--warn);
  background: var(--warn-soft);
  color: var(--warn);
  animation: voice-transcribe 1.4s var(--ease) infinite;
}

.voice-orb.is-live {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
  --voice-listen-pulse: var(--accent-soft);
  animation: voice-listen 2.4s var(--ease) infinite;
}

.voice-orb.is-live.is-capturing {
  border-color: transparent;
  background: var(--accent);
  color: var(--fg-on-accent);
  box-shadow: var(--glow-brand);
  animation: voice-pulse 1s var(--ease) infinite;
}

.voice-orb.is-live.is-transcribing {
  border-color: var(--warn);
  background: var(--warn-soft);
  color: var(--warn);
  box-shadow: none;
  animation: voice-transcribe 1.2s var(--ease) infinite;
}

/* Off is a true device-level kill switch: the orb goes quiet (no glow, no
   breathing) but stays clickable — a click reopens this menu, not the mic. */
.voice-orb.is-off {
  color: var(--fg-3);
  border-color: var(--border-subtle);
  background: var(--bg-elevated);
  box-shadow: none;
  animation: none;
}

@keyframes voice-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(0, 215, 215, 0.20), var(--glow-brand);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(0, 215, 215, 0.08), var(--glow-brand);
  }
}

@keyframes voice-listen {
  0%, 100% {
    box-shadow: 0 0 0 0 var(--voice-listen-pulse);
  }
  50% {
    box-shadow: 0 0 0 5px var(--voice-listen-pulse);
  }
}

@keyframes voice-transcribe {
  0%, 100% {
    box-shadow: 0 0 0 0 var(--warn-soft);
  }
  50% {
    box-shadow: 0 0 0 5px var(--warn-soft);
  }
}

/* ── voice mode menu ──────────────────────────────────────────────────── */
/* A popover of the three honest mic modes (off / push-to-talk / hands-free)
   anchored above the orb inside .voice-wrap (position: relative). The orb is
   the mic; a small trigger opens this menu. Rust owns the active mode and
   whether the menu is mounted — this only skins the emitted panel. */

.voice-menu {
  position: absolute;
  bottom: calc(100% + 8px);
  /* The orb sits at the composer's LEFT edge — anchor the popover's left
     to the wrap so it grows rightward over the composer, not off-viewport. */
  left: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  min-width: 224px;
  padding: 6px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--elev-3);
  animation: voice-menu-enter var(--dur-fast) var(--ease) both;
}

@keyframes voice-menu-enter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mode row — icon left, label + description stacked right. The three are
   direct children placed by grid, so source order never breaks the layout. */
.voice-menu__item {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 8px;
  row-gap: 2px;
  align-items: center;
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.voice-menu__item:hover {
  background: var(--bg-hover);
}

.voice-menu__item:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-menu__item.is-active {
  background: var(--accent-soft);
}

.voice-menu__item-icon {
  grid-row: 1 / span 2;
  grid-column: 1;
  align-self: center;
  display: inline-flex;
  font-size: 14px;
  color: var(--fg-3);
}

.voice-menu__item-icon .icon,
.voice-menu__item-icon svg {
  width: 1em;
  height: 1em;
}

.voice-menu__item.is-active .voice-menu__item-icon {
  color: var(--accent);
}

.voice-menu__item-label {
  grid-column: 2;
  grid-row: 1;
  font-size: 12px;
  line-height: 1.3;
  color: var(--fg);
}

.voice-menu__item-desc {
  grid-column: 2;
  grid-row: 2;
  font-size: 11px;
  line-height: 1.35;
  color: var(--fg-3);
}

.voice-menu__error {
  color: var(--err);
  font-size: 11px;
  line-height: 1.35;
  padding-inline: 8px;
  margin: 0;
}

/* Hr-like separator between mode rows and the spoken-replies toggle. */
.voice-menu__divider {
  height: 0;
  margin: 6px 2px;
  border: 0;
  border-top: 1px solid var(--border-subtle);
}

/* "Microphone" group label — non-interactive section header for the
   radio-group portion of the voice menu. */
.voice-menu__group-label {
  display: block;
  padding: 6px 8px 2px;
  font-size: 10px;
  line-height: 1.4;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-3);
  user-select: none;
}

/* Spoken-replies toggle — a quiet row with a trailing state dot (::after);
   is-on blooms the dot aqua to read as "replies on". */
.voice-menu__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg);
  font-size: 12px;
  line-height: 1.3;
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.voice-menu__toggle:hover {
  background: var(--bg-hover);
}

.voice-menu__toggle:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.voice-menu__toggle::after {
  content: "";
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: var(--border-strong);
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease);
}

.voice-menu__toggle.is-on::after {
  background: var(--accent);
  box-shadow: 0 0 6px var(--accent-soft);
}

/* Privacy footnote — small, muted, the last word on what leaves the device. */
.voice-menu__note {
  padding: 6px 8px 2px;
  font-size: 10px;
  line-height: 1.4;
  color: var(--fg-3);
}

/* ── voice trigger + live chip ────────────────────────────────────────── */
/* The trigger is a ghost chevron that opens the menu — quiet by default,
   found on hover/focus, with a 0.35 floor so touch users always reach it.
   The live chip shows only while hands-free is hot: a pulsing aqua dot. */

.voice-trigger {
  appearance: none;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--fg-3);
  font-size: 12px;
  opacity: 0.35;
  cursor: pointer;
  transition:
    opacity var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-trigger .icon,
.voice-trigger svg {
  width: 1em;
  height: 1em;
}

.voice-wrap:hover .voice-trigger,
.voice-wrap:focus-within .voice-trigger,
.voice-wrap:has(.voice-menu) .voice-trigger {
  opacity: 1;
}

.voice-trigger:hover {
  color: var(--fg);
  opacity: 1;
}

.voice-trigger:focus-visible {
  outline: none;
  opacity: 1;
  box-shadow: var(--focus-ring);
  border-radius: var(--radius-sm);
}

.voice-live-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  background: var(--bg-raised);
  color: var(--fg-2);
  font-size: 10px;
  line-height: 1;
  cursor: pointer;
  transition:
    border-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-live-chip:hover {
  border-color: var(--border-strong);
  color: var(--fg);
}

.voice-live-chip:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Pulsing dot — the hot aqua behind --glow-live (ocean-7 / --accent-bright),
   the same live family the call styles ring speaking tiles with. */
.voice-live-chip::before {
  content: "";
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--accent-bright);
  box-shadow: 0 0 6px var(--accent-soft);
  animation: voice-chip-pulse 1.4s var(--ease) infinite;
}

@keyframes voice-chip-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

/* The orb speaks through color and its tooltip; a permanent caption under
   it is knob noise. */
.voice-hint { display: none; }

/* ── text composer ────────────────────────────────────────────────────── */

.ocean-composer__input {
  grid-area: input;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 32px;
  max-height: 240px;
  overflow-y: hidden;
  padding: 4px 4px 6px;
  resize: none;
  border: none;
  border-radius: 0;
  outline: none;
  background: transparent;
  box-shadow: none;
  color: var(--fg);
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.45;
  transition:
    background var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-composer__input::placeholder {
  color: var(--fg-3);
}

.ocean-composer__input:focus,
.ocean-composer__input:focus-visible {
  outline: none;
  box-shadow: none;
}

.ocean-composer__input:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Trailing action — one circular icon slot shared by Send (idle, accent) and
   Stop (streaming, halt-red). Mutually exclusive; both live in `action`. */
.ocean-composer__send,
.ocean-composer__halt {
  grid-area: action;
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--ctl-h);      /* 34px circle */
  height: var(--ctl-h);
  padding: 0;
  font-size: 18px;          /* drives the 1em icon */
  border: none;
  border-radius: var(--radius-pill);
  cursor: pointer;
  transition:
    transform var(--dur-fast) var(--ease),
    filter var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    opacity var(--dur-fast) var(--ease);
}

.ocean-composer__send {
  background: var(--accent);
  box-shadow: var(--elev-1);
  color: var(--fg-on-accent);
}

.ocean-composer__send:hover {
  filter: brightness(1.12);
}

.ocean-composer__send:focus-visible {
  outline: none;
  box-shadow: var(--elev-1), var(--focus-ring);
}

.ocean-composer__send:active {
  transform: translateY(1px);
  box-shadow: var(--pressed);
}

.ocean-composer__send:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
  filter: none;
  box-shadow: none;
}

.ocean-composer__halt {
  background: var(--err-soft);
  box-shadow: var(--elev-1);
  color: var(--err);
}

.ocean-composer__halt:hover {
  filter: brightness(1.12);
}

.ocean-composer__halt:focus-visible {
  outline: none;
  box-shadow: var(--elev-1), var(--focus-ring);
}

.ocean-composer__halt:active {
  transform: translateY(1px);
  box-shadow: var(--pressed);
}

@media (prefers-reduced-motion: reduce) {
  .ocean-composer,
  .voice-orb,
  .voice-menu,
  .voice-trigger,
  .voice-live-chip,
  .ocean-composer__input,
  .ocean-composer__send,
  .ocean-composer__halt {
    transition: none;
    animation: none;
  }

  .voice-orb.is-recording,
  .voice-orb.is-transcribing,
  .voice-orb.is-live,
  .voice-orb.is-live.is-capturing,
  .voice-orb.is-live.is-transcribing {
    animation: none;
  }

  .voice-live-chip::before {
    animation: none;
  }
}

/* ── Realtime voice chat (voice phases 2/3) ──────────────────────────────
   While a voice session is connecting/live and no components are on screen
   (`.voice-chat-active` on the app root), the composer's text input, send
   button, and per-turn controls hide — kept mounted so their signals stay
   alive — and the orb takes center stage: floated above the composer,
   enlarged, its glow breathing with the live mic level (`--voice-level`,
   0..1, written by the level meter in voice/realtime.rs). Once the voice
   agent renders components (`.voice-chat-docked` replaces `-active`) the
   orb returns to its normal composer slot so they get the room. Both
   Send and Stop share the action slot and hide in this mode. These states are
   class-driven; stage Off removes them and reverts everything. */

.voice-chat-active .ocean-composer__input,
.voice-chat-active .ocean-composer__send,
.voice-chat-active .ocean-composer__halt,
.voice-chat-active .ocean-turn-controls,
.voice-chat-active .ocean-slash-menu {
  display: none;
}

.ocean-slash-menu {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(100% + 8px);
  max-height: 280px;
  overflow: auto;
  z-index: 40;
  padding: 6px;
  border-radius: var(--radius-md, 10px);
  background: var(--surface-elevated, var(--bg-elevated, #12141a));
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
  box-shadow: var(--shadow-md, 0 8px 28px rgba(0,0,0,0.35));
}
.ocean-slash-menu__group + .ocean-slash-menu__group {
  margin-top: 6px;
}
.ocean-slash-menu__group-label {
  padding: 4px 8px;
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--fg-muted, #8b93a7);
}
.ocean-slash-menu__row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
  width: 100%;
  text-align: left;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--fg, #e8ecf5);
  cursor: pointer;
}
.ocean-slash-menu__row.is-selected,
.ocean-slash-menu__row:hover {
  background: var(--surface-hover, rgba(255,255,255,0.06));
}
.ocean-slash-menu__row.is-disabled {
  opacity: 0.45;
  cursor: default;
}
.ocean-slash-menu__title {
  font-size: 13px;
}
.ocean-slash-menu__alias {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
  color: var(--fg-muted, #8b93a7);
}
.ocean-slash-menu__hint {
  grid-column: 1 / -1;
  font-size: 11px;
  color: var(--fg-muted, #8b93a7);
}

.voice-chat-active .voice-wrap {
  /* Release the named grid placement: an abs-pos grid child WITH a grid-area
     uses that area as its containing block, which pinned the orb to the tiny
     orb track instead of centering over the whole composer. */
  grid-area: auto;
  position: absolute;
  left: 50%;
  bottom: calc(100% + 56px);
  transform: translateX(-50%);
  z-index: 30;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.voice-chat-active .voice-orb {
  width: 108px;
  height: 108px;
  border-radius: 50%;
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
  /* Mic-reactive breathing: scale + glow track the live level. Deliberately
     NOT transitioned — the level writes at ~60Hz and must track instantly. */
  transform: scale(calc(1 + var(--voice-level, 0) * 0.16));
  box-shadow: 0 0 calc(16px + 44px * var(--voice-level, 0)) var(--accent-soft);
  /* Promotion/dock animates size only; transform/box-shadow stay untransitioned
     so the ~60Hz level writes track instantly. Color transitions kept. */
  transition:
    width 300ms var(--ease),
    height 300ms var(--ease),
    border-color var(--dur-fast) var(--ease),
    background var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.voice-chat-active .voice-orb__glyph .icon,
.voice-chat-active .voice-orb__glyph svg {
  width: 44px;
  height: 44px;
}

.voice-chat-active .voice-hint {
  position: static;
  text-align: center;
  font-size: 13px;
  color: var(--fg-2);
}

@media (prefers-reduced-motion: reduce) {
  .voice-chat-active .voice-orb {
    transition: none;
    transform: none;
    box-shadow: 0 0 16px var(--accent-soft);
  }
}

