/* Ocean Surface — agent component system.
   Authority: docs/OCEAN_WEB_SURFACE_DESIGN.md. Keep class names load-bearing. */

/* ---- Shared component surfaces ---------------------------------------- */
.component-kanban,
.component-form,
.component-table,
.component-progress,
.component-markdown,
.component-dashboard,
.component-chart,
.component-timeline,
.component-stats,
.component-filetree,
.component-diff,
.component-code,
.component-gallery,
.block--map,
.block--video {
  margin: 8px 0;
  max-width: 100%;
  min-width: 0;
}

.component-kanban,
.component-form form,
.component-table,
.component-progress,
.component-markdown,
.component-dashboard,
.component-chart,
.component-timeline,
.component-stats,
.component-filetree,
.component-diff,
.component-code,
.component-callout,
.component-gallery,
.component-confirm,
.block--component-unknown {
  background: var(--sheen), var(--bg-elevated);
  box-shadow: var(--elev-2);
  border-radius: var(--radius-lg);
  box-sizing: border-box;
  color: var(--fg);
  padding: 16px;
}

.kanban-column__header,
.component-form__title,
.form-field__label,
.data-table th,
.progress-label,
.component-chart__title,
.diff__filename,
.code__lang,
.stat-card__label,
.filetree__root,
.gallery__cap {
